import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Kernel 日报 2026-11-19","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/19.md","filePath":"notes/kernel-digest/2026/11/19.md"}'),n={name:"notes/kernel-digest/2026/11/19.md"};function l(s,e,d,i,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-19" tabindex="-1">Kernel 日报 2026-11-19 <a class="header-anchor" href="#kernel-日报-2026-11-19" aria-label="Permalink to &quot;Kernel 日报 2026-11-19&quot;">​</a></h1><blockquote><p>生成时间：2026-11-19T01:44:16Z｜共 46 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-19 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_8a20252aa0b4-·-nginx2root-remote-code-execution-vulnerabilities-in-nginx" tabindex="-1"><code>8a20252aa0b4</code> · <a href="https://lwn.net/Articles/1108362/" target="_blank" rel="noreferrer">NGINX2Root: Remote Code Execution vulnerabilities in nginx</a> <a class="header-anchor" href="#_8a20252aa0b4-·-nginx2root-remote-code-execution-vulnerabilities-in-nginx" aria-label="Permalink to &quot;`8a20252aa0b4` · [NGINX2Root: Remote Code Execution vulnerabilities in nginx](https://lwn.net/Articles/1108362/)&quot;">​</a></h3><p><em>jzb｜lwn｜其他动态</em></p><p>Xint 披露了 NGINX Web 服务器的五个严重漏洞，其中最严重者可让未认证攻击者在启用 HTTP/2 的服务器上远程执行命令。此外还报告了一个自 4.15 内核引入的 SCTP 子系统本地提权（LPE）漏洞，与 NGINX 漏洞链式利用可获得主机 root 权限，目前内核补丁尚未发布。</p><blockquote><p><strong>学习价值</strong>：展示了漏洞链（RCE + 内核 LPE）的完整攻击路径，对理解内核子系统漏洞的实际安全影响很有参考价值。</p></blockquote><h3 id="_6bf038ba38cc-·-patch-net-next-v2-00-12-psp-introduce-socket-less-associations" tabindex="-1"><code>6bf038ba38cc</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/12] psp: introduce socket-less associations</a> <a class="header-anchor" href="#_6bf038ba38cc-·-patch-net-next-v2-00-12-psp-introduce-socket-less-associations" aria-label="Permalink to &quot;`6bf038ba38cc` · [[PATCH net-next v2 00/12] psp: introduce socket-less associations](https://lore.kernel.org/all/20261119013103.1092559-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml｜其他动态</em></p><p>本系列补丁引入不绑定 TCP socket 的 PSP association，使 PSP 封装与加密可应用于转发流量，实现透明加密。socket-less PSP 通过 PSP netlink family 管理，Tx association 将对端密钥存于设备中并以 ID 标识供 tc psp encap action 使用，Rx 侧内核不保存状态。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰阐述了 PSP socket-less 架构的整体设计动机与方案，适合先读此篇再深入各补丁。</p></blockquote><h3 id="b3c657b6daae-·-patch-net-next-v2-00-11-net-extra-tx-headroom-for-local-egress" tabindex="-1"><code>b3c657b6daae</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/11] net: extra TX headroom for local egress</a> <a class="header-anchor" href="#b3c657b6daae-·-patch-net-next-v2-00-11-net-extra-tx-headroom-for-local-egress" aria-label="Permalink to &quot;`b3c657b6daae` · [[PATCH net-next v2 00/11] net: extra TX headroom for local egress](https://lore.kernel.org/all/20261119013830.36935-1-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev｜网络</em></p><p>本系列（v2）解决本地生成流量 headroom 不足的问题：本地 UDP、raw、AF_PACKET 以及 copy 模式下的 AF_XDP 包只按 needed_headroom 分配空间，当 XDP 或 TC 程序需要更多空间时，每个包都会触发 skb 重新分配或拷贝。典型场景包括 veth peer 上的 XDP 程序需要 XDP_PACKET_HEADROOM（256 字节）、TC egress 程序添加头部、以及跨 namespace 经 veth 发送时在宿主 uplink 的 TC egress 程序处理。系列通过统一的额外 headroom 分配消除这些逐包开销。</p><blockquote><p><strong>学习价值</strong>：完整展示了从性能问题定位到跨子系统（XDP/TC/veth）统一解决方案的设计过程，对学习网络数据路径优化很有价值。</p></blockquote><h3 id="f2bb2221e73d-·-patch-mm-damon-core-fix-damos-walk-hang-with-zero-watermarks-interval" tabindex="-1"><code>f2bb2221e73d</code> · <a href="https://lore.kernel.org/all/20261118235012.14859-1-evanfengff@gmail.com/" target="_blank" rel="noreferrer">[PATCH] mm/damon/core: fix damos_walk() hang with zero watermarks interval</a> <a class="header-anchor" href="#f2bb2221e73d-·-patch-mm-damon-core-fix-damos-walk-hang-with-zero-watermarks-interval" aria-label="Permalink to &quot;`f2bb2221e73d` · [[PATCH] mm/damon/core: fix damos_walk() hang with zero watermarks interval](https://lore.kernel.org/all/20261118235012.14859-1-evanfengff@gmail.com/)&quot;">​</a></h3><p><em>Yifan Feng (<a href="mailto:evanfengff@gmail.com" target="_blank" rel="noreferrer">evanfengff@gmail.com</a>)｜linux-mm｜内存管理</em></p><p>修复 damos_walk() 在 watermarks interval 为零（DAMON sysfs 接口默认值）时的挂起问题。kdamond_wait_activation() 在所有 scheme 被 watermarks 停用时取消 walk 请求，但 interval 为零时直接返回，导致 kdamond 主循环中 walk 请求既未完成也未取消，damos_walk() 可能永久等待。</p><blockquote><p><strong>学习价值</strong>：展示了 DAMON 内部 kdamond 状态机与 damos_walk 生命周期的交互，对学习 DAMON 子系统的并发与状态管理很有帮助。</p></blockquote><h3 id="_9b51fe706ab4-·-patch-0-4-drm-tyr-use-pin-init-self-referential-support" tabindex="-1"><code>9b51fe706ab4</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 0/4] drm/tyr: use pin-init self-referential support</a> <a class="header-anchor" href="#_9b51fe706ab4-·-patch-0-4-drm-tyr-use-pin-init-self-referential-support" aria-label="Permalink to &quot;`9b51fe706ab4` · [[PATCH 0/4] drm/tyr: use pin-init self-referential support](https://lore.kernel.org/all/20261118233727.3147222-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux｜Rust in Linux</em></p><p>本系列补丁在 drm/tyr 驱动中利用 pin-init 的 self-referential 支持替代 Arc，以更准确地表达资源生命周期由其 owner 界定的语义。同时清理了生命周期命名、修复生成 pin-init 代码中的 Clippy 警告，并用 ScopeGuard 简化 firmware 加载的清理逻辑。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核驱动中如何用 pin-init 自引用结构替代 Arc 来建模所有权关系，是学习内核 Rust 生命周期管理的优秀实例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（2 条）</li><li><strong>网络</strong>（19 条）</li><li><strong>Rust in Linux</strong>（10 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（14 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_8ef7dde34f4e-·-wine-merges-remote-opengl-swapchain-image-presentation-cef-now-works-with-wayland" tabindex="-1"><code>8ef7dde34f4e</code> · <a href="https://www.phoronix.com/news/Wine-OpenGL-Cross-Proc-Render" target="_blank" rel="noreferrer">Wine Merges Remote OpenGL Swapchain Image Presentation, CEF Now Works With Wayland</a> <a class="header-anchor" href="#_8ef7dde34f4e-·-wine-merges-remote-opengl-swapchain-image-presentation-cef-now-works-with-wayland" aria-label="Permalink to &quot;`8ef7dde34f4e` · [Wine Merges Remote OpenGL Swapchain Image Presentation, CEF Now Works With Wayland](https://www.phoronix.com/news/Wine-OpenGL-Cross-Proc-Render)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Wine 11.23 合并了远程 OpenGL swapchain 图像呈现（remote OpenGL swapchain image presentation）的重大改进，同时改善了 Wine 原生 Wayland 驱动的兼容性，使 CEF 在 Wayland 下正常工作。</p><blockquote><p><strong>学习价值</strong>：属于用户态图形兼容层（Wine/Wayland）的进展，与内核内存管理无关，对内核学习价值较低。</p></blockquote><h3 id="f2bb2221e73d-·-patch-mm-damon-core-fix-damos-walk-hang-with-zero-watermarks-interval-1" tabindex="-1"><code>f2bb2221e73d</code> · <a href="https://lore.kernel.org/all/20261118235012.14859-1-evanfengff@gmail.com/" target="_blank" rel="noreferrer">[PATCH] mm/damon/core: fix damos_walk() hang with zero watermarks interval</a> <a class="header-anchor" href="#f2bb2221e73d-·-patch-mm-damon-core-fix-damos-walk-hang-with-zero-watermarks-interval-1" aria-label="Permalink to &quot;`f2bb2221e73d` · [[PATCH] mm/damon/core: fix damos_walk() hang with zero watermarks interval](https://lore.kernel.org/all/20261118235012.14859-1-evanfengff@gmail.com/)&quot;">​</a></h3><p><em>Yifan Feng (<a href="mailto:evanfengff@gmail.com" target="_blank" rel="noreferrer">evanfengff@gmail.com</a>)｜linux-mm</em></p><p>修复 damos_walk() 在 watermarks interval 为零（DAMON sysfs 接口默认值）时的挂起问题。kdamond_wait_activation() 在所有 scheme 被 watermarks 停用时取消 walk 请求，但 interval 为零时直接返回，导致 kdamond 主循环中 walk 请求既未完成也未取消，damos_walk() 可能永久等待。</p><blockquote><p><strong>学习价值</strong>：展示了 DAMON 内部 kdamond 状态机与 damos_walk 生命周期的交互，对学习 DAMON 子系统的并发与状态管理很有帮助。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_3753b51a0ec1-·-patch-net-next-v2-06-12-net-sched-add-act-psp-for-psp-transport-mode" tabindex="-1"><code>3753b51a0ec1</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-7-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 06/12] net/sched: add act_psp for psp transport mode</a> <a class="header-anchor" href="#_3753b51a0ec1-·-patch-net-next-v2-06-12-net-sched-add-act-psp-for-psp-transport-mode" aria-label="Permalink to &quot;`3753b51a0ec1` · [[PATCH net-next v2 06/12] net/sched: add act_psp for psp transport mode](https://lore.kernel.org/all/20261119013103.1092559-7-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>新增 tc action act_psp，用于 PSP transport mode 的封装与加密。encap 动作将 PSP Tx association 以 METADATA_PSP dst 的形式挂到 skb 上，数据包必须在 association 对应 PSP 设备的主 netdev 上发送才能被加密，其他设备会丢弃。ingress 上的 encap 不受支持，因为路由、netfilter、bpf redirect 等路径可能替换 dst 导致明文外发。</p><blockquote><p><strong>学习价值</strong>：展示了 tc action 与硬件加密路径（metadata_dst 机制）结合的设计思路，是理解数据面加密与 tc 集成的好案例。</p></blockquote><h3 id="c4891414dc77-·-patch-net-next-v2-07-12-net-sched-flower-add-psp-spi-psp-ver-and-psp-dev-matches" tabindex="-1"><code>c4891414dc77</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-8-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 07/12] net/sched: flower: add psp_spi, psp_ver, and psp_dev matches</a> <a class="header-anchor" href="#c4891414dc77-·-patch-net-next-v2-07-12-net-sched-flower-add-psp-spi-psp-ver-and-psp-dev-matches" aria-label="Permalink to &quot;`c4891414dc77` · [[PATCH net-next v2 07/12] net/sched: flower: add psp_spi, psp_ver, and psp_dev matches](https://lore.kernel.org/all/20261119013103.1092559-8-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>为 flower classifier 新增 psp_spi、psp_ver 和 psp_dev 三个匹配字段，取自解密后数据包上由设备附着的 PSP Rx 状态（SKB_EXT_PSP）。通过这些匹配可将 tc 规则绑定到特定的 Rx SPI，配合 psp decap action 实现解密后转发等操作。</p><blockquote><p><strong>学习价值</strong>：演示了 flow dissector key 扩展与 flower 匹配字段的添加流程，是学习 tc filter 体系扩展的实用参考。</p></blockquote><h3 id="_7b541ef686ee-·-patch-net-next-v2-05-12-net-add-metadata-psp-dst-to-carry-a-psp-association-on-an-skb" tabindex="-1"><code>7b541ef686ee</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-6-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 05/12] net: add METADATA_PSP dst to carry a psp association on an skb</a> <a class="header-anchor" href="#_7b541ef686ee-·-patch-net-next-v2-05-12-net-add-metadata-psp-dst-to-carry-a-psp-association-on-an-skb" aria-label="Permalink to &quot;`7b541ef686ee` · [[PATCH net-next v2 05/12] net: add METADATA_PSP dst to carry a psp association on an skb](https://lore.kernel.org/all/20261119013103.1092559-6-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>新增一种 metadata_dst 类型用于持有 PSP association 的引用，使无 socket 的 skb（如由 tc action 处理的包）也能携带 association。psp_skb_get_assoc_rcu() 先检查 METADATA_PSP 再回退到 socket，因此 mlx5、netdevsim 等现有驱动 Tx 路径无需修改即可加密此类数据包。</p><blockquote><p><strong>学习价值</strong>：深入展示了 metadata_dst 机制在无 socket 数据包中传递元数据的用法，对理解内核数据面元数据传递很有价值。</p></blockquote><h3 id="d1988aca8f12-·-patch-net-net-mlx5e-skip-hairpin-entries-not-ready-in-debugfs-dump" tabindex="-1"><code>d1988aca8f12</code> · <a href="https://lore.kernel.org/all/20261119012707.555494-1-lcy8047@gmail.com/" target="_blank" rel="noreferrer">[PATCH net] net/mlx5e: Skip hairpin entries not ready in debugfs dump</a> <a class="header-anchor" href="#d1988aca8f12-·-patch-net-net-mlx5e-skip-hairpin-entries-not-ready-in-debugfs-dump" aria-label="Permalink to &quot;`d1988aca8f12` · [[PATCH net] net/mlx5e: Skip hairpin entries not ready in debugfs dump](https://lore.kernel.org/all/20261119012707.555494-1-lcy8047@gmail.com/)&quot;">​</a></h3><p><em>Changyul Lee (<a href="mailto:lcy8047@gmail.com" target="_blank" rel="noreferrer">lcy8047@gmail.com</a>)｜lkml</em></p><p>修复 mlx5e hairpin debugfs dump 中的空指针/错误指针解引用问题：hairpin 条目在创建完成前就已加入表，读取 hairpin_table_dump 可能命中正在创建或创建失败的条目。补丁跳过这些未就绪条目。由静态分析工具发现，仅做了编译测试。</p><blockquote><p><strong>学习价值</strong>：一个典型的 debugfs 接口竞态修复案例，展示了静态分析工具发现内核 bug 的实际价值。</p></blockquote><h3 id="_34320513e17e-·-patch-net-next-v2-11-11-selftests-net-tx-extra-headroom-test-the-veth-attribute" tabindex="-1"><code>34320513e17e</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-12-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 11/11] selftests: net: tx_extra_headroom: test the veth attribute</a> <a class="header-anchor" href="#_34320513e17e-·-patch-net-next-v2-11-11-selftests-net-tx-extra-headroom-test-the-veth-attribute" aria-label="Permalink to &quot;`34320513e17e` · [[PATCH net-next v2 11/11] selftests: net: tx_extra_headroom: test the veth attribute](https://lore.kernel.org/all/20261119013830.36935-12-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>为 veth 的 VETH_INFO_TX_EXTRA_HEADROOM 属性添加 selftest：通过 YNL 创建带 64 字节 headroom 的 veth 对，将 peer 移入另一个 netns，验证两端读数一致，且 XDP 挂载时数值为 64+256（两者相加），同时验证超过 512 的值被拒绝。测试辅助代码将 RtnlFamily socket 交给垃圾回收，与 link_netns.py 的做法一致。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 YNL 编写 netlink 属性的端到端测试，是学习 netlink selftest 框架的好范例。</p></blockquote><h3 id="_62596faaf7cd-·-patch-net-next-v2-10-11-netlink-specs-rt-link-add-veth-attributes" tabindex="-1"><code>62596faaf7cd</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-11-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 10/11] netlink: specs: rt-link: add veth attributes</a> <a class="header-anchor" href="#_62596faaf7cd-·-patch-net-next-v2-10-11-netlink-specs-rt-link-add-veth-attributes" aria-label="Permalink to &quot;`62596faaf7cd` · [[PATCH net-next v2 10/11] netlink: specs: rt-link: add veth attributes](https://lore.kernel.org/all/20261119013830.36935-11-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>在 rt-link.yaml 中描述 veth 属性，使 YNL 能够设置和读取 VETH_INFO_TX_EXTRA_HEADROOM。由于 YNL 通过 get_hdr_inc 从源码树包含 linux/veth.h，需要将头文件保护宏加上 _UAPI 前缀（参照 commit 8066e388be48 的做法），headers_install 会剥离该前缀，安装后的头文件不变。</p><blockquote><p><strong>学习价值</strong>：揭示了 YNL 规范文件与 UAPI 头文件的协作机制，以及 headers_install 前缀剥离这一鲜为人知的细节。</p></blockquote><h3 id="_6707faee764e-·-patch-net-next-v2-09-11-veth-add-veth-info-tx-extra-headroom" tabindex="-1"><code>6707faee764e</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-10-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 09/11] veth: add VETH_INFO_TX_EXTRA_HEADROOM</a> <a class="header-anchor" href="#_6707faee764e-·-patch-net-next-v2-09-11-veth-add-veth-info-tx-extra-headroom" aria-label="Permalink to &quot;`6707faee764e` · [[PATCH net-next v2 09/11] veth: add VETH_INFO_TX_EXTRA_HEADROOM](https://lore.kernel.org/all/20261119013830.36935-10-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>新增 VETH_INFO_TX_EXTRA_HEADROOM 属性，允许 CNI 插件在创建 veth 对时为两端设备设置额外 headroom，避免数据包在宿主机上行链路被 TC egress 程序封装时重新分配。该值与 IFLA_NETKIT_HEADROOM 类似创建后不可修改，存储在 struct veth_priv 中，并通过新增的 ndo_get_tx_extra_headroom 回调供核心层在重算 tx_extra_headroom 时读取。</p><blockquote><p><strong>学习价值</strong>：展示了 ndo 回调扩展设备能力的典型设计模式，以及容器网络场景下 headroom 优化的实际动机。</p></blockquote><h3 id="_4500afff8152-·-patch-net-next-v2-08-11-selftests-bpf-test-the-tx-extra-headroom-decl-tag" tabindex="-1"><code>4500afff8152</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-9-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 08/11] selftests/bpf: Test the tx_extra_headroom decl tag</a> <a class="header-anchor" href="#_4500afff8152-·-patch-net-next-v2-08-11-selftests-bpf-test-the-tx-extra-headroom-decl-tag" aria-label="Permalink to &quot;`4500afff8152` · [[PATCH net-next v2 08/11] selftests/bpf: Test the tx_extra_headroom decl tag](https://lore.kernel.org/all/20261119013830.36935-9-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>为 BPF verifier 的 tx_extra_headroom decl tag 添加 selftest：验证 verifier 接受等于 NETDEV_TX_EXTRA_HEADROOM_MAX（512 字节）的 tag，拒绝超限值、带加号的值以及同一程序上的重复 tag。</p><blockquote><p><strong>学习价值</strong>：演示了如何针对 verifier 新语法编写边界条件测试，是学习 BPF verifier 测试方法的实用参考。</p></blockquote><h3 id="_167d555e7e56-·-patch-net-next-v2-07-11-selftests-net-tx-extra-headroom-test-a-push-at-tc-egress" tabindex="-1"><code>167d555e7e56</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-8-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 07/11] selftests: net: tx_extra_headroom: test a push at TC egress</a> <a class="header-anchor" href="#_167d555e7e56-·-patch-net-next-v2-07-11-selftests-net-tx-extra-headroom-test-a-push-at-tc-egress" aria-label="Permalink to &quot;`167d555e7e56` · [[PATCH net-next v2 07/11] selftests: net: tx_extra_headroom: test a push at TC egress](https://lore.kernel.org/all/20261119013830.36935-8-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>为 tcx egress 程序上的 tx_extra_headroom decl tag 添加测试用例。测试程序用 bpf_skb_adjust_room() 在 MAC 头后 push 20 或 30 字节并记录 skb-&gt;head 是否变化（变化即代表 pskb_expand_head() 重新分配了数据包）。验证：无 tag 时 push 触发重分配、有 tag 时不触发；tag 程序的 tx_extra_headroom 为 20，卸载后归零；peer 挂 XDP 时数值相加。</p><blockquote><p><strong>学习价值</strong>：通过 skb-&gt;head 变化检测数据包重分配的技巧非常巧妙，对理解 skb headroom 机制很有帮助。</p></blockquote><h3 id="_1d4a2c47f39a-·-patch-net-next-v2-06-11-bpf-tcx-set-tx-extra-headroom-from-a-decl-tag-on-egress-programs" tabindex="-1"><code>1d4a2c47f39a</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-7-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 06/11] bpf, tcx: Set tx_extra_headroom from a decl tag on egress programs</a> <a class="header-anchor" href="#_1d4a2c47f39a-·-patch-net-next-v2-06-11-bpf-tcx-set-tx-extra-headroom-from-a-decl-tag-on-egress-programs" aria-label="Permalink to &quot;`1d4a2c47f39a` · [[PATCH net-next v2 06/11] bpf, tcx: Set tx_extra_headroom from a decl tag on egress programs](https://lore.kernel.org/all/20261119013830.36935-7-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>允许 TC egress 的 BPF 程序通过 BTF decl tag 声明其将 push 的字节数，例如 <strong>attribute</strong>((btf_decl_tag(&quot;tx_extra_headroom:64&quot;)))，verifier 在程序加载时解析该 tag（类似 exception_callback 的处理方式）并存入 struct bpf_prog_aux，从而让本地生成的数据包在分配时就预留足够 headroom，避免 bpf_skb_adjust_room() 触发 pskb_expand_head() 重分配。</p><blockquote><p><strong>学习价值</strong>：展示了 decl tag 作为 BPF 程序元信息传递通道的设计思路，连接了 BPF verifier 与网络栈的 headroom 优化。</p></blockquote><h3 id="c757967d4390-·-patch-net-next-v2-05-11-selftests-net-add-tx-extra-headroom-test" tabindex="-1"><code>c757967d4390</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-6-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 05/11] selftests: net: add tx_extra_headroom test</a> <a class="header-anchor" href="#c757967d4390-·-patch-net-next-v2-05-11-selftests-net-add-tx-extra-headroom-test" aria-label="Permalink to &quot;`c757967d4390` · [[PATCH net-next v2 05/11] selftests: net: add tx_extra_headroom test](https://lore.kernel.org/all/20261119013830.36935-6-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>测试 XDP 挂载到 veth 一端时内核自动设置另一端 tx_extra_headroom 的行为：generic XDP 会对 headroom 不足 XDP_PACKET_HEADROOM（256 字节）的 skb 进行拷贝，设置后本地生成的数据包即有足够 headroom 而无需拷贝。测试覆盖六种发送路径：IPv4/IPv6 的 UDP、raw socket（IPPROTO_RAW）、AF_PACKET 和 copy 模式的 AF_XDP。</p><blockquote><p><strong>学习价值</strong>：覆盖六种不同 skb 分配路径的测试设计，是理解本地发包 headroom 分配全貌的绝佳材料。</p></blockquote><h3 id="f02c8e1df810-·-patch-net-next-v2-04-11-selftests-net-add-flag-to-send-a-frame-in-xdp-helper" tabindex="-1"><code>f02c8e1df810</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-5-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 04/11] selftests: net: add flag to send a frame in xdp_helper</a> <a class="header-anchor" href="#f02c8e1df810-·-patch-net-next-v2-04-11-selftests-net-add-flag-to-send-a-frame-in-xdp-helper" aria-label="Permalink to &quot;`f02c8e1df810` · [[PATCH net-next v2 04/11] selftests: net: add flag to send a frame in xdp_helper](https://lore.kernel.org/all/20261119013830.36935-5-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>为 xdp_helper 添加 -t 选项，接收一个十六进制表示的以太网帧，创建 TX ring 并通过 AF_XDP TX 路径发送后退出，sendto() 失败返回 1。由于 veth 不支持 AF_XDP zerocopy，socket 运行在 copy 模式，内核在 xsk_build_skb() 中分配 skb 时会使用额外 headroom。</p><blockquote><p><strong>学习价值</strong>：展示了如何扩展测试基础设施支持 AF_XDP TX 路径，对学习 AF_XDP copy 模式的内核行为有帮助。</p></blockquote><h3 id="_27bcd77bd5eb-·-patch-net-next-v2-03-11-net-set-tx-extra-headroom-of-the-peer-on-xdp-attach" tabindex="-1"><code>27bcd77bd5eb</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-4-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 03/11] net: set tx_extra_headroom of the peer on XDP attach</a> <a class="header-anchor" href="#_27bcd77bd5eb-·-patch-net-next-v2-03-11-net-set-tx-extra-headroom-of-the-peer-on-xdp-attach" aria-label="Permalink to &quot;`27bcd77bd5eb` · [[PATCH net-next v2 03/11] net: set tx_extra_headroom of the peer on XDP attach](https://lore.kernel.org/all/20261119013830.36935-4-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>XDP 需要 XDP_PACKET_HEADROOM（256 字节），而本地生成的数据包只预留 needed_headroom，导致 veth/netkit peer 上的 XDP 程序（generic XDP 的 netif_skb_check_for_xdp() 和 native XDP 的 veth_convert_skb_to_xdp_buff()）拷贝每个数据包。本补丁在 peer 挂载 XDP 程序期间，将设备 tx_extra_headroom 设为 XDP_PACKET_HEADROOM 减去 needed_headroom，通过 netdev_update_tx_extra_headroom() 在 XDP 程序挂载/卸载时（包括 bond 等上层设备经 netif_xdp_propagate() 传播）重算。</p><blockquote><p><strong>学习价值</strong>：清晰展示了 XDP headroom 需求与本地发包路径之间的矛盾及解决方案，是理解 XDP 与 skb 分配交互的好案例。</p></blockquote><h3 id="_25ac3cb4813e-·-patch-net-next-v2-02-11-net-reserve-extra-tx-headroom-for-local-egress" tabindex="-1"><code>25ac3cb4813e</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-3-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 02/11] net: reserve extra TX headroom for local egress</a> <a class="header-anchor" href="#_25ac3cb4813e-·-patch-net-next-v2-02-11-net-reserve-extra-tx-headroom-for-local-egress" aria-label="Permalink to &quot;`25ac3cb4813e` · [[PATCH net-next v2 02/11] net: reserve extra TX headroom for local egress](https://lore.kernel.org/all/20261119013830.36935-3-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>将本地发送路径中为输出设备分配数据包时的 LL_RESERVED_SPACE()/LL_RESERVED_SPACE_EX() 替换为 netdev_get_alloc_headroom()/netdev_get_alloc_headroom_hlen()，覆盖 __ip_append_data() 和 __ip6_append_data()（UDP、ICMP、ping 及无 IP_HDRINCL 的 raw socket）、raw_send_hdrinc()/rawv6_send_hdrinc()、三条 AF_PACKET 发送路径，以及原本自行计算的 AF_XDP copy 模式（改用 netdev_get_alloc_needed_headroom()）。</p><blockquote><p><strong>学习价值</strong>：梳理了内核所有本地发包的 skb 分配路径，是学习 IP/IPv6/packet socket 发送路径的系统性地图。</p></blockquote><h3 id="e6ea4bbae161-·-patch-net-next-v2-01-11-net-add-tx-extra-headroom-and-netdev-get-alloc-headroom" tabindex="-1"><code>e6ea4bbae161</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-2-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 01/11] net: add tx_extra_headroom and netdev_get_alloc_headroom()</a> <a class="header-anchor" href="#e6ea4bbae161-·-patch-net-next-v2-01-11-net-add-tx-extra-headroom-and-netdev-get-alloc-headroom" aria-label="Permalink to &quot;`e6ea4bbae161` · [[PATCH net-next v2 01/11] net: add tx_extra_headroom and netdev_get_alloc_headroom()](https://lore.kernel.org/all/20261119013830.36935-2-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>该补丁为 struct net_device 新增 tx_extra_headroom 字段，并引入 netdev_get_alloc_headroom() 辅助函数。背景是 TC egress 上的 BPF 程序常需为封装等操作在包头前压入额外头部，而本地生成的 UDP、raw 和 AF_PACKET 流量只按 LL_RESERVED_SPACE() 分配 headroom，不足时 BPF helper 不得不为每个包重新分配并拷贝 skb。新机制允许驱动或用户预先声明额外 headroom，避免逐包开销。</p><blockquote><p><strong>学习价值</strong>：有助于理解 skb headroom 分配机制与 TC egress BPF 程序的性能优化路径，是 netdev 与 eBPF 交叉领域的典型案例。</p></blockquote><h3 id="b3c657b6daae-·-patch-net-next-v2-00-11-net-extra-tx-headroom-for-local-egress-1" tabindex="-1"><code>b3c657b6daae</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/11] net: extra TX headroom for local egress</a> <a class="header-anchor" href="#b3c657b6daae-·-patch-net-next-v2-00-11-net-extra-tx-headroom-for-local-egress-1" aria-label="Permalink to &quot;`b3c657b6daae` · [[PATCH net-next v2 00/11] net: extra TX headroom for local egress](https://lore.kernel.org/all/20261119013830.36935-1-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>本系列（v2）解决本地生成流量 headroom 不足的问题：本地 UDP、raw、AF_PACKET 以及 copy 模式下的 AF_XDP 包只按 needed_headroom 分配空间，当 XDP 或 TC 程序需要更多空间时，每个包都会触发 skb 重新分配或拷贝。典型场景包括 veth peer 上的 XDP 程序需要 XDP_PACKET_HEADROOM（256 字节）、TC egress 程序添加头部、以及跨 namespace 经 veth 发送时在宿主 uplink 的 TC egress 程序处理。系列通过统一的额外 headroom 分配消除这些逐包开销。</p><blockquote><p><strong>学习价值</strong>：完整展示了从性能问题定位到跨子系统（XDP/TC/veth）统一解决方案的设计过程，对学习网络数据路径优化很有价值。</p></blockquote><h3 id="_6e8c015d57c7-·-patch-net-next-v2-11-12-selftests-tc-testing-add-tests-for-the-psp-action" tabindex="-1"><code>6e8c015d57c7</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-12-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 11/12] selftests: tc-testing: add tests for the psp action</a> <a class="header-anchor" href="#_6e8c015d57c7-·-patch-net-next-v2-11-12-selftests-tc-testing-add-tests-for-the-psp-action" aria-label="Permalink to &quot;`6e8c015d57c7` · [[PATCH net-next v2 11/12] selftests: tc-testing: add tests for the psp action](https://lore.kernel.org/all/20261119013103.1092559-12-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>为 tc-testing 自测框架新增 PSP（传输安全协议）action 的测试，覆盖 psp decap action 的添加、替换、删除和 flush，验证不存在的 association 会被拒绝，并测试 flower 过滤器对 psp_spi、psp_ver、psp_dev 的匹配及越界值拒绝。测试匹配内核 extack 消息以避免与 tc 自身参数检查混淆，创建 association 依赖 PSP netlink family 和 PSP 设备。</p><blockquote><p><strong>学习价值</strong>：展示了如何为内核网络特性编写 tc-testing 自测用例，可学习 netlink 驱动的测试组织方式与 extack 校验实践。</p></blockquote><h3 id="cadecdb5ad2f-·-patch-net-next-v2-12-12-documentation-networking-psp-document-socket-less-associations" tabindex="-1"><code>cadecdb5ad2f</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-13-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 12/12] Documentation: networking: psp: document socket-less associations</a> <a class="header-anchor" href="#cadecdb5ad2f-·-patch-net-next-v2-12-12-documentation-networking-psp-document-socket-less-associations" aria-label="Permalink to &quot;`cadecdb5ad2f` · [[PATCH net-next v2 12/12] Documentation: networking: psp: document socket-less associations](https://lore.kernel.org/all/20261119013103.1092559-13-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>更新 Documentation/networking/psp.rst，描述 PSP association 在 socket 与 tc 两种使用场景下的差异，记录 socket-less PSP 的新 netlink 命令，并说明密钥轮换时用户态需自行处理的事项（内核不为 socket-less Rx SPI 保存状态）。同时文档化 psp tc action、flower 的 psp_spi/psp_ver/psp_dev 匹配项以及 PSP 设备统计信息。</p><blockquote><p><strong>学习价值</strong>：通过 PSP 协议文档可了解内核安全传输协议的 association 生命周期与密钥轮换设计，是学习协议文档化的好样本。</p></blockquote><h3 id="_699cf426ac71-·-patch-net-next-v2-10-12-selftests-tc-testing-run-dependson-probes-outside-the-test-namespace" tabindex="-1"><code>699cf426ac71</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-11-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 10/12] selftests: tc-testing: run dependsOn probes outside the test namespace</a> <a class="header-anchor" href="#_699cf426ac71-·-patch-net-next-v2-10-12-selftests-tc-testing-run-dependson-probes-outside-the-test-namespace" aria-label="Permalink to &quot;`699cf426ac71` · [[PATCH net-next v2 10/12] selftests: tc-testing: run dependsOn probes outside the test namespace](https://lore.kernel.org/all/20261119013103.1092559-11-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜netdev</em></p><p>修复 tc-testing 框架中 dependsOn 探测命令的执行位置问题：探测原本作为 execute 阶段命令运行，但发生在测试 namespace 创建之前，被 nsPlugin 加上 &quot;ip netns exec tcut&quot; 前缀后必然失败，导致所有依赖 nsPlugin 的探测测试（如 mirred blockid、tunnel_key nofrag）被跳过。补丁将探测改为独立的 &quot;probe&quot; 阶段，在 base namespace 中运行，并更新了 README 和 AddingTestCases.txt。</p><blockquote><p><strong>学习价值</strong>：揭示了 tc-testing 框架的 namespace 隔离机制与阶段化执行模型，对理解内核网络测试基础设施运作方式很有帮助。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="af2649ef2094-·-patch-v1-docs-rust-mention-track-caller-for-functions-that-panic" tabindex="-1"><code>af2649ef2094</code> · <a href="https://lore.kernel.org/all/20261118234452.2621985-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1] docs: rust: mention #[track_caller] for functions that panic</a> <a class="header-anchor" href="#af2649ef2094-·-patch-v1-docs-rust-mention-track-caller-for-functions-that-panic" aria-label="Permalink to &quot;`af2649ef2094` · [[PATCH v1] docs: rust: mention #[track_caller] for functions that panic](https://lore.kernel.org/all/20261118234452.2621985-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>在 Rust 编码规范文档的 &quot;# Panics&quot; 章节补充一条指引：可能 panic 的函数应同时标注 #[track_caller]，使 panic 消息显示调用者的位置而非函数内部行号，便于定位问题。</p><blockquote><p><strong>学习价值</strong>：小而实用的 Rust 内核编码规范改进，提醒学习者关注 panic 信息的可调试性。</p></blockquote><h3 id="_8b0bdd7ee86e-·-patch-4-4-drm-tyr-use-scopeguard-for-firmware-loading-cleanup" tabindex="-1"><code>8b0bdd7ee86e</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-5-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 4/4] drm/tyr: use ScopeGuard for firmware loading cleanup</a> <a class="header-anchor" href="#_8b0bdd7ee86e-·-patch-4-4-drm-tyr-use-scopeguard-for-firmware-loading-cleanup" aria-label="Permalink to &quot;`8b0bdd7ee86e` · [[PATCH 4/4] drm/tyr: use ScopeGuard for firmware loading cleanup](https://lore.kernel.org/all/20261118233727.3147222-5-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>在 drm/tyr 驱动的固件加载代码中改用 ScopeGuard 处理清理逻辑：固件 section 加载失败时自动调用 vm.kill()，成功时通过 dismiss 取消守卫，替代了原先嵌套闭包加显式错误检查的写法，代码从 32 行减至 27 行。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核驱动中 ScopeGuard 的惯用法，是学习内核 Rust 错误处理与资源清理模式的简洁范例。</p></blockquote><h3 id="_0187e9cf4288-·-patch-3-4-drm-tyr-use-pin-init-self-referential-support" tabindex="-1"><code>0187e9cf4288</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-4-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 3/4] drm/tyr: use pin-init self-referential support</a> <a class="header-anchor" href="#_0187e9cf4288-·-patch-3-4-drm-tyr-use-pin-init-self-referential-support" aria-label="Permalink to &quot;`0187e9cf4288` · [[PATCH 3/4] drm/tyr: use pin-init self-referential support](https://lore.kernel.org/all/20261118233727.3147222-4-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>利用 pin-init 新支持的 self-referential struct 能力重构 drm/tyr 驱动：MMIO 映射、MMU 和固件 VM 等生命周期受限于所有者的资源，原先需借助 Arc 共享，现在改用借用（borrow）方式，省去独立分配和引用计数。通过一个超越 &#39;fw 的存在性生命周期隐藏 VM 与其 sections 共享的资源生命周期不变量，使 Firmware 类型只需一个生命周期参数。</p><blockquote><p><strong>学习价值</strong>：是理解 pin-init 自引用结构、存在性生命周期与借用替代 Arc 的进阶案例，对学习内核 Rust 所有权建模极具参考价值。</p></blockquote><h3 id="e033de96ae89-·-patch-2-4-rust-pin-init-internal-suppress-multiple-bound-locations" tabindex="-1"><code>e033de96ae89</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-3-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 2/4] rust: pin-init: internal: suppress multiple_bound_locations</a> <a class="header-anchor" href="#e033de96ae89-·-patch-2-4-rust-pin-init-internal-suppress-multiple-bound-locations" aria-label="Permalink to &quot;`e033de96ae89` · [[PATCH 2/4] rust: pin-init: internal: suppress multiple_bound_locations](https://lore.kernel.org/all/20261118233727.3147222-3-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>pin-init 生成的 __drop_order_check() 会将存在性生命周期边界与推断出的字段 outlives 边界组合，导致同一约束（如 &#39;res: &#39;fw）同时出现在泛型参数列表和 where 子句中，触发 Clippy 的 multiple_bound_locations lint。补丁仅对生成的 drop-order 检查代码允许该 lint，保留用户代码中的检查。修复 commit 73cf61724648 引入的问题。</p><blockquote><p><strong>学习价值</strong>：展示了内核 Rust 宏生成代码与 Clippy lint 的交互处理方式，可了解 pin-init 内部实现与 drop 顺序检查机制。</p></blockquote><h3 id="_4cad13ece4d6-·-patch-1-4-drm-tyr-name-resource-lifetimes-after-their-types" tabindex="-1"><code>4cad13ece4d6</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-2-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 1/4] drm/tyr: name resource lifetimes after their types</a> <a class="header-anchor" href="#_4cad13ece4d6-·-patch-1-4-drm-tyr-name-resource-lifetimes-after-their-types" aria-label="Permalink to &quot;`4cad13ece4d6` · [[PATCH 1/4] drm/tyr: name resource lifetimes after their types](https://lore.kernel.org/all/20261118233727.3147222-2-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>为 drm/tyr 驱动中固件、buffer、VM 和 MMU 类型的资源生命周期参数重命名：原先统一使用 &#39;drm，尽管各参数实际只在其所属类型范围内有效。补丁将生命周期参数改为反映各自类型作用域的名称，为后续将资源所有权转换为 self-referential pin-init 形式做准备。</p><blockquote><p><strong>学习价值</strong>：示范了 Rust 生命周期参数命名的最佳实践，说明清晰的生命周期命名对大型驱动重构的重要性。</p></blockquote><h3 id="_9b51fe706ab4-·-patch-0-4-drm-tyr-use-pin-init-self-referential-support-1" tabindex="-1"><code>9b51fe706ab4</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 0/4] drm/tyr: use pin-init self-referential support</a> <a class="header-anchor" href="#_9b51fe706ab4-·-patch-0-4-drm-tyr-use-pin-init-self-referential-support-1" aria-label="Permalink to &quot;`9b51fe706ab4` · [[PATCH 0/4] drm/tyr: use pin-init self-referential support](https://lore.kernel.org/all/20261118233727.3147222-1-dakr@kernel.org/)&quot;">​</a></h3><p><em>Danilo Krummrich (<a href="mailto:dakr@kernel.org" target="_blank" rel="noreferrer">dakr@kernel.org</a>)｜rust-for-linux</em></p><p>本系列补丁在 drm/tyr 驱动中利用 pin-init 的 self-referential 支持替代 Arc，以更准确地表达资源生命周期由其 owner 界定的语义。同时清理了生命周期命名、修复生成 pin-init 代码中的 Clippy 警告，并用 ScopeGuard 简化 firmware 加载的清理逻辑。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核驱动中如何用 pin-init 自引用结构替代 Arc 来建模所有权关系，是学习内核 Rust 生命周期管理的优秀实例。</p></blockquote><h3 id="dc51fabf7cd3-·-patch-v1-rust-time-add-track-caller-to-delta-division-and-remainder" tabindex="-1"><code>dc51fabf7cd3</code> · <a href="https://lore.kernel.org/all/20261118230708.2599659-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v1] rust: time: add #[track_caller] to Delta division and remainder</a> <a class="header-anchor" href="#dc51fabf7cd3-·-patch-v1-rust-time-add-track-caller-to-delta-division-and-remainder" aria-label="Permalink to &quot;`dc51fabf7cd3` · [[PATCH v1] rust: time: add #[track_caller] to Delta division and remainder](https://lore.kernel.org/all/20261118230708.2599659-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>为 rust/kernel/time.rs 中 Delta 类型的 div() 和 rem_nanos() 方法添加 #[track_caller] 属性。这两个方法在除数为零或 i64::MIN 除以 -1 时会 panic，原 panic 信息指向 time.rs 内部行号，添加该属性后 panic 消息将显示调用者的位置，便于定位错误。</p><blockquote><p><strong>学习价值</strong>：小而实用的补丁，演示了 #[track_caller] 在内核 Rust 代码调试中的作用，值得学习者了解。</p></blockquote><h3 id="_47a993e73778-·-patch-v4-2-2-pwm-th1520-fix-32-bit-build-with-compile-test" tabindex="-1"><code>47a993e73778</code> · <a href="https://lore.kernel.org/all/20261118224826.2491684-3-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v4 2/2] pwm: th1520: Fix 32-bit build with COMPILE_TEST</a> <a class="header-anchor" href="#_47a993e73778-·-patch-v4-2-2-pwm-th1520-fix-32-bit-build-with-compile-test" aria-label="Permalink to &quot;`47a993e73778` · [[PATCH v4 2/2] pwm: th1520: Fix 32-bit build with COMPILE_TEST](https://lore.kernel.org/all/20261118224826.2491684-3-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>修复 pwm_th1520 驱动在 32-bit ARM 上启用 COMPILE_TEST 时的链接错误：undefined symbol __aeabi_uldivmod。原因是驱动在纳秒与时钟周期转换时直接用 / 运算符对 u64 相除，32-bit ARM 上会生成对编译器运行时函数的调用，而内核不提供该函数。改用新增的 div64_u64() 和 div64_u64_round_up() 辅助函数，计算结果不变。</p><blockquote><p><strong>学习价值</strong>：揭示了 32-bit 架构上 u64 除法的链接陷阱，是理解内核为何提供 math64.h 辅助函数的好案例。</p></blockquote><h3 id="_13be2a8e524a-·-patch-v4-1-2-rust-math-add-div64-u64-and-div64-u64-round-up" tabindex="-1"><code>13be2a8e524a</code> · <a href="https://lore.kernel.org/all/20261118224826.2491684-2-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v4 1/2] rust: math: add div64_u64() and div64_u64_round_up()</a> <a class="header-anchor" href="#_13be2a8e524a-·-patch-v4-1-2-rust-math-add-div64-u64-and-div64-u64-round-up" aria-label="Permalink to &quot;`13be2a8e524a` · [[PATCH v4 1/2] rust: math: add div64_u64() and div64_u64_round_up()](https://lore.kernel.org/all/20261118224826.2491684-2-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>在 kernel crate 中新增 math 模块，提供 Rust 版本的 div64_u64() 和 div64_u64_round_up()，对应 C 代码 include/linux/math64.h 中的同名辅助函数。背景是 32-bit 架构上 Rust 代码对 u64 使用 / 运算符会触发对 __aeabi_uldivmod() 等编译器运行时函数的调用，而内核不提供这些函数导致构建失败。</p><blockquote><p><strong>学习价值</strong>：体现了 Rust 内核抽象层如何镜像 C 内核的既有基础设施，是学习跨语言 API 对齐设计的参考。</p></blockquote><h3 id="_4257e62ad356-·-patch-v4-0-2-rust-add-u64-division-helpers-and-fix-the-pwm-th1520-32-bit-build" tabindex="-1"><code>4257e62ad356</code> · <a href="https://lore.kernel.org/all/20261118224826.2491684-1-tomo@flapping.org/" target="_blank" rel="noreferrer">[PATCH v4 0/2] rust: add u64 division helpers and fix the pwm_th1520 32-bit build</a> <a class="header-anchor" href="#_4257e62ad356-·-patch-v4-0-2-rust-add-u64-division-helpers-and-fix-the-pwm-th1520-32-bit-build" aria-label="Permalink to &quot;`4257e62ad356` · [[PATCH v4 0/2] rust: add u64 division helpers and fix the pwm_th1520 32-bit build](https://lore.kernel.org/all/20261118224826.2491684-1-tomo@flapping.org/)&quot;">​</a></h3><p><em>FUJITA Tomonori (<a href="mailto:tomo@flapping.org" target="_blank" rel="noreferrer">tomo@flapping.org</a>)｜rust-for-linux</em></p><p>本系列补丁共两部分：第一部分为 kernel crate 新增 math 模块，提供 Rust 版的 div64_u64() 和 DIV64_U64_ROUND_UP()；第二部分在 TH1520 PWM 驱动中使用这些辅助函数，修复其 32-bit 构建失败问题。该系列计划通过 Rust tree 合入，并提及与另一份 chenhan 的 math.rs 补丁存在模块头冲突需协调。</p><blockquote><p><strong>学习价值</strong>：展示了内核社区中功能重叠补丁的协调过程，以及补丁系列的组织方式，对理解社区协作流程有帮助。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="a56ce1578f48-·-next-20261118-linux-next" tabindex="-1"><code>a56ce1578f48</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261118-2026-11-18" target="_blank" rel="noreferrer">next-20261118: linux-next</a> <a class="header-anchor" href="#a56ce1578f48-·-next-20261118-linux-next" aria-label="Permalink to &quot;`a56ce1578f48` · [next-20261118: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261118-2026-11-18)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 18 日发布 next-20261118 版本。linux-next 是主线合并前的集成测试树，汇集各子系统树的待合入补丁。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 发布可帮助学习者提前了解即将进入主线的代码变更，是观察内核开发节奏的窗口。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_0065de93ace9-·-lwn-net-weekly-edition-for-november-19-2026" tabindex="-1"><code>0065de93ace9</code> · <a href="https://lwn.net/Articles/1107147/" target="_blank" rel="noreferrer">[$] LWN.net Weekly Edition for November 19, 2026</a> <a class="header-anchor" href="#_0065de93ace9-·-lwn-net-weekly-edition-for-november-19-2026" aria-label="Permalink to &quot;`0065de93ace9` · [[$] LWN.net Weekly Edition for November 19, 2026](https://lwn.net/Articles/1107147/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>LWN.net 2026年11月19日周刊，涵盖 C++26 标准、Buildroot、更快的 futex、Zellij、Julia 语言等前沿内容，以及 Glasswing、NGINX RCE、XRAID、curl 三十年、Rust 1.100 等简讯和安全更新公告。</p><blockquote><p><strong>学习价值</strong>：适合作为了解当周开源与内核生态动态的概览入口，但深度技术内容需订阅阅读。</p></blockquote><h3 id="_8a20252aa0b4-·-nginx2root-remote-code-execution-vulnerabilities-in-nginx-1" tabindex="-1"><code>8a20252aa0b4</code> · <a href="https://lwn.net/Articles/1108362/" target="_blank" rel="noreferrer">NGINX2Root: Remote Code Execution vulnerabilities in nginx</a> <a class="header-anchor" href="#_8a20252aa0b4-·-nginx2root-remote-code-execution-vulnerabilities-in-nginx-1" aria-label="Permalink to &quot;`8a20252aa0b4` · [NGINX2Root: Remote Code Execution vulnerabilities in nginx](https://lwn.net/Articles/1108362/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Xint 披露了 NGINX Web 服务器的五个严重漏洞，其中最严重者可让未认证攻击者在启用 HTTP/2 的服务器上远程执行命令。此外还报告了一个自 4.15 内核引入的 SCTP 子系统本地提权（LPE）漏洞，与 NGINX 漏洞链式利用可获得主机 root 权限，目前内核补丁尚未发布。</p><blockquote><p><strong>学习价值</strong>：展示了漏洞链（RCE + 内核 LPE）的完整攻击路径，对理解内核子系统漏洞的实际安全影响很有参考价值。</p></blockquote><h3 id="_5020ae59da99-·-julia-1-13-brings-repl-improvements-and-more" tabindex="-1"><code>5020ae59da99</code> · <a href="https://lwn.net/Articles/1108153/" target="_blank" rel="noreferrer">[$] Julia 1.13 brings REPL improvements and more</a> <a class="header-anchor" href="#_5020ae59da99-·-julia-1-13-brings-repl-improvements-and-more" aria-label="Permalink to &quot;`5020ae59da99` · [[$] Julia 1.13 brings REPL improvements and more](https://lwn.net/Articles/1108153/)&quot;">​</a></h3><p><em>jake｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Julia 1.13 于 2026 年 9 月 10 日发布，带来增强的 REPL、图形化安装器、更流畅的开发者体验以及多项性能改进。Julia 是面向高性能数值计算领域的通用语言，在科学与数学社区日益流行。</p><blockquote><p><strong>学习价值</strong>：与 Linux 内核无直接关系，仅适合关注系统级编程语言生态的读者泛读。</p></blockquote><h3 id="_26c9cd18a314-·-security-updates-for-wednesday" tabindex="-1"><code>26c9cd18a314</code> · <a href="https://lwn.net/Articles/1108354/" target="_blank" rel="noreferrer">Security updates for Wednesday</a> <a class="header-anchor" href="#_26c9cd18a314-·-security-updates-for-wednesday" aria-label="Permalink to &quot;`26c9cd18a314` · [Security updates for Wednesday](https://lwn.net/Articles/1108354/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>AlmaLinux、Debian、Fedora、Mageia 等发行版发布例行安全更新，涉及 kernel、bind、podman、ghostscript 等大量软件包。</p><blockquote><p><strong>学习价值</strong>：可作为跟踪各发行版内核及关键组件安全补丁的常规信息源，无深入技术细节。</p></blockquote><h3 id="accf7f770e79-·-dell-xps-14-da14260-powered-by-intel-panther-lake-delivers-nice-linux-experience" tabindex="-1"><code>accf7f770e79</code> · <a href="https://www.phoronix.com/review/dell-xps-14-panther-lake" target="_blank" rel="noreferrer">Dell XPS 14 DA14260 Powered By Intel Panther Lake Delivers Nice Linux Experience</a> <a class="header-anchor" href="#accf7f770e79-·-dell-xps-14-da14260-powered-by-intel-panther-lake-delivers-nice-linux-experience" aria-label="Permalink to &quot;`accf7f770e79` · [Dell XPS 14 DA14260 Powered By Intel Panther Lake Delivers Nice Linux Experience](https://www.phoronix.com/review/dell-xps-14-panther-lake)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Dell XPS 14（DA14260）搭载 Intel Core Ultra Series 3 &quot;Panther Lake&quot; 处理器，凭借 Xe3 Arc B390 显卡和良好能效，已通过 Ubuntu 26.04 LTS 认证，开箱即用的 Linux 体验流畅且性能出色。</p><blockquote><p><strong>学习价值</strong>：属于硬件兼容性资讯，可帮助了解新 Intel 平台的 Linux 支持成熟度，但无内核技术细节。</p></blockquote><h3 id="b32d178691e9-·-nvidia-620-73-04-linux-driver-released-with-bug-fixes" tabindex="-1"><code>b32d178691e9</code> · <a href="https://www.phoronix.com/news/NVIDIA-620.73.04-Linux" target="_blank" rel="noreferrer">NVIDIA 620.73.04 Linux Driver Released With Bug FIxes</a> <a class="header-anchor" href="#b32d178691e9-·-nvidia-620-73-04-linux-driver-released-with-bug-fixes" aria-label="Permalink to &quot;`b32d178691e9` · [NVIDIA 620.73.04 Linux Driver Released With Bug FIxes](https://www.phoronix.com/news/NVIDIA-620.73.04-Linux)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>NVIDIA 发布 R620 分支的第二个公开版本 620.73.04 Linux 驱动，主要是 bug 修复，紧随两周前发布的首个公开版本 620.70.06。</p><blockquote><p><strong>学习价值</strong>：仅为显卡驱动版本动态，对内核学习者价值有限。</p></blockquote><h3 id="_20d202c4ce85-·-multikernel-linux-comes-to-arm64-mklinux-7-0-mk5-released" tabindex="-1"><code>20d202c4ce85</code> · <a href="https://www.phoronix.com/news/Multi-Kernel-mklinux-7.0-mk5" target="_blank" rel="noreferrer">Multikernel Linux Comes To ARM64, mklinux 7.0-mk5 Released</a> <a class="header-anchor" href="#_20d202c4ce85-·-multikernel-linux-comes-to-arm64-mklinux-7-0-mk5-released" aria-label="Permalink to &quot;`20d202c4ce85` · [Multikernel Linux Comes To ARM64, mklinux 7.0-mk5 Released](https://www.phoronix.com/news/Multi-Kernel-mklinux-7.0-mk5)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>允许在同一物理机上运行多个独立内核实例的树外 Multikernel Linux 补丁发布新版本 7.0-mk5，现已支持 ARM64 平台。</p><blockquote><p><strong>学习价值</strong>：展示了多内核并行架构这一非常规设计思路，有助于拓宽对内核启动与隔离机制的理解，但属树外补丁。</p></blockquote><h3 id="db1595852b05-·-patch-net-next-v2-09-12-selftests-drv-net-psp-test-that-software-encap-on-ingress-drops" tabindex="-1"><code>db1595852b05</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-10-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 09/12] selftests: drv-net: psp: test that software encap on ingress drops</a> <a class="header-anchor" href="#db1595852b05-·-patch-net-next-v2-09-12-selftests-drv-net-psp-test-that-software-encap-on-ingress-drops" aria-label="Permalink to &quot;`db1595852b05` · [[PATCH net-next v2 09/12] selftests: drv-net: psp: test that software encap on ingress drops](https://lore.kernel.org/all/20261119013103.1092559-10-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>该补丁为 PSP（传输安全协议）添加 selftests：验证在 veth 入口方向配置软件 encap 时数据包会被丢弃，包括 IPv4/IPv6 路由转发流量和发往本地地址的流量均不得以明文到达。</p><blockquote><p><strong>学习价值</strong>：是学习 PSP 协议数据面行为和 veth/tc selftests 编写方法的良好实例。</p></blockquote><h3 id="_97bdc989466c-·-patch-net-next-v2-08-12-selftests-drv-net-psp-test-socket-less-associations-and-the-tc-psp-action" tabindex="-1"><code>97bdc989466c</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-9-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 08/12] selftests: drv-net: psp: test socket-less associations and the tc psp action</a> <a class="header-anchor" href="#_97bdc989466c-·-patch-net-next-v2-08-12-selftests-drv-net-psp-test-socket-less-associations-and-the-tc-psp-action" aria-label="Permalink to &quot;`97bdc989466c` · [[PATCH net-next v2 08/12] selftests: drv-net: psp: test socket-less associations and the tc psp action](https://lore.kernel.org/all/20261119013103.1092559-9-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>该补丁覆盖 socket-less PSP 关联命令和 tc psp action 的测试：入口方向用 flower 匹配 psp_spi/psp_ver/psp_dev 并用 psp decap 移除 PSP 状态，出口方向用 psp encap 为数据包附加 Tx 关联，由设备完成加密。</p><blockquote><p><strong>学习价值</strong>：展示了 tc action 与 flower 匹配器在 PSP 加解密路径中的实际用法，对学习 tc 数据面编程很有帮助。</p></blockquote><h3 id="_6bf038ba38cc-·-patch-net-next-v2-00-12-psp-introduce-socket-less-associations-1" tabindex="-1"><code>6bf038ba38cc</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-1-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/12] psp: introduce socket-less associations</a> <a class="header-anchor" href="#_6bf038ba38cc-·-patch-net-next-v2-00-12-psp-introduce-socket-less-associations-1" aria-label="Permalink to &quot;`6bf038ba38cc` · [[PATCH net-next v2 00/12] psp: introduce socket-less associations](https://lore.kernel.org/all/20261119013103.1092559-1-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>本系列补丁引入不绑定 TCP socket 的 PSP association，使 PSP 封装与加密可应用于转发流量，实现透明加密。socket-less PSP 通过 PSP netlink family 管理，Tx association 将对端密钥存于设备中并以 ID 标识供 tc psp encap action 使用，Rx 侧内核不保存状态。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰阐述了 PSP socket-less 架构的整体设计动机与方案，适合先读此篇再深入各补丁。</p></blockquote><h3 id="_1fa6af06a7d0-·-patch-net-next-v2-04-12-psp-add-support-for-socket-less-psp-associations" tabindex="-1"><code>1fa6af06a7d0</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-5-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 04/12] psp: add support for socket-less psp associations</a> <a class="header-anchor" href="#_1fa6af06a7d0-·-patch-net-next-v2-04-12-psp-add-support-for-socket-less-psp-associations" aria-label="Permalink to &quot;`1fa6af06a7d0` · [[PATCH net-next v2 04/12] psp: add support for socket-less psp associations](https://lore.kernel.org/all/20261119013103.1092559-5-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>在现有 socket 绑定的 PSP association 基础上，新增以 ID 引用、不绑定 socket 的 Tx association，供 tc psp action 等其他栈组件挂载到数据包。Rx 侧无需 association，用户态通过 rx-spi-alloc 操作分配 SPI，再用 tc filter 匹配对应的 SPI、版本和 PSP 设备。</p><blockquote><p><strong>学习价值</strong>：展示了如何将加密状态从 socket 生命周期解耦的设计演进，有助于理解内核中状态管理抽象的扩展方式。</p></blockquote><h3 id="_27a26f72704d-·-patch-net-next-v2-03-12-psp-declare-psp-assoc-set-tx-in-psp-h" tabindex="-1"><code>27a26f72704d</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-4-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 03/12] psp: declare psp_assoc_set_tx() in psp.h</a> <a class="header-anchor" href="#_27a26f72704d-·-patch-net-next-v2-03-12-psp-declare-psp-assoc-set-tx-in-psp-h" aria-label="Permalink to &quot;`27a26f72704d` · [[PATCH net-next v2 03/12] psp: declare psp_assoc_set_tx() in psp.h](https://lore.kernel.org/all/20261119013103.1092559-4-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>将 psp_assoc_set_tx() 从 static 改为非 static 并在 net/psp/psp.h 中声明，使 socket-less PSP association 能以与 socket 相同的方式安装 Tx 密钥。改动仅涉及 psp.h 和 psp_sock.c 两个文件。</p><blockquote><p><strong>学习价值</strong>：一个典型的接口重构小补丁，可学习内核代码中函数可见性调整的常见做法。</p></blockquote><h3 id="_13e3b6bafa59-·-patch-net-next-v2-01-12-psp-get-netns-from-net-device-instead-of-sock" tabindex="-1"><code>13e3b6bafa59</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-2-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 01/12] psp: get netns from net_device instead of sock</a> <a class="header-anchor" href="#_13e3b6bafa59-·-patch-net-next-v2-01-12-psp-get-netns-from-net-device-instead-of-sock" aria-label="Permalink to &quot;`13e3b6bafa59` · [[PATCH net-next v2 01/12] psp: get netns from net_device instead of sock](https://lore.kernel.org/all/20261119013103.1092559-2-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>由于 tc psp action 等新途径挂载的 PSP association 使 skb 不再必然关联 socket，改为从发送的 net_device 获取 netns。psp_write_headers() 中外层源端口范围在 socket 场景下仍显式使用 sock_net(sk) 以保持原有行为。</p><blockquote><p><strong>学习价值</strong>：展示了引入新数据路径时 netns 获取来源的迁移考量，提醒学习者注意 netns 语义在多路径下的正确性。</p></blockquote><h3 id="_7c2fb318f002-·-patch-net-next-v2-02-12-psp-take-the-psp-nexthdr-from-the-packet-on-encap" tabindex="-1"><code>7c2fb318f002</code> · <a href="https://lore.kernel.org/all/20261119013103.1092559-3-toddfreed@meta.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 02/12] psp: take the psp nexthdr from the packet on encap</a> <a class="header-anchor" href="#_7c2fb318f002-·-patch-net-next-v2-02-12-psp-take-the-psp-nexthdr-from-the-packet-on-encap" aria-label="Permalink to &quot;`7c2fb318f002` · [[PATCH net-next v2 02/12] psp: take the psp nexthdr from the packet on encap](https://lore.kernel.org/all/20261119013103.1092559-3-toddfreed@meta.com/)&quot;">​</a></h3><p><em>Todd Freed (<a href="mailto:toddfreed@meta.com" target="_blank" rel="noreferrer">toddfreed@meta.com</a>)｜lkml</em></p><p>psp_dev_encapsulate() 原先硬编码 IPPROTO_TCP 作为 PSP next header，现改为从原始数据包的 IP header 中读取，以支持 socket-less 场景下的 UDP 流量。同时显式拒绝 IPv4/IPv6 分片和 IPv6 扩展头等 transport header 位置无法确定的情况。</p><blockquote><p><strong>学习价值</strong>：体现了协议封装中对 L4 header 定位的边界条件处理，是学习网络协议栈健壮性设计的好例子。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>b3c657b6daae</code> · <a href="https://lore.kernel.org/all/20261119013830.36935-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/11] net: extra TX headroom for local egress</a></li><li><code>f2bb2221e73d</code> · <a href="https://lore.kernel.org/all/20261118235012.14859-1-evanfengff@gmail.com/" target="_blank" rel="noreferrer">[PATCH] mm/damon/core: fix damos_walk() hang with zero watermarks interval</a></li><li><code>9b51fe706ab4</code> · <a href="https://lore.kernel.org/all/20261118233727.3147222-1-dakr@kernel.org/" target="_blank" rel="noreferrer">[PATCH 0/4] drm/tyr: use pin-init self-referential support</a></li></ul>',218)])])}const f=t(n,[["render",l]]);export{m as __pageData,f as default};
